<script setup lang="ts">
import { requestAPI } from './api'

import ImportDetails from './ImportDetails.vue'
import UserSources from './UserSources.vue'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {NButton,NInput,NInputNumber,NSelect,NSwitch,NModal,NForm,NFormItem,NAlert,NDataTable,NTag,NPagination} from 'naive-ui'
const props=defineProps<{routes:any[];nodes:any[]}>()
const plans=ref<any[]>([]),accounts=ref<any[]>([]),busy=ref(false),error=ref(''),notice=ref('')
const accountSearch=ref(''),accountPage=ref(1)
const selectedAccountIds=ref<string[]>([])
const matchingAccounts=computed(()=>accounts.value.filter(row=>row.account.username.toLowerCase().includes(accountSearch.value.trim().toLowerCase())))
const visibleAccounts=computed(()=>matchingAccounts.value.slice((accountPage.value-1)*20,accountPage.value*20))
watch(accountSearch,()=>{accountPage.value=1})
const modal=ref(''),form=ref<any>({}),selected=ref<any>(null),sessions=ref<any[]>([]),delivery=ref('')
const routeOptions=computed(()=>[{label:'用户自行添加 Emby',value:''},...props.routes.filter(r=>!r.owner_account_id).map(r=>({label:r.alias,value:r.id}))])
const planOptions=computed(()=>plans.value.map(p=>({label:p.name,value:p.id})))
const date=(n:number)=>n?new Date(n*1000).toLocaleString('zh-CN'):'不限'
const bytes=(n:number)=>n>=1073741824?(n/1073741824).toFixed(2)+' GiB':(n/1048576).toFixed(2)+' MiB'
async function api(path:string,method='GET',body?:any){const {response:r,data:data}=await requestAPI('/api/v1/'+path,method,body);if(!r.ok)throw Error(data.error||'请求失败');return data}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function refresh(){[plans.value,accounts.value]=await Promise.all([api('access-plans'),api('access-accounts')]);if(selected.value)selected.value=accounts.value.find(v=>v.account.id===selected.value.account.id)||null}
let refreshTimer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{run(refresh);refreshTimer=setInterval(()=>{if(!busy.value&&!modal.value&&!document.hidden)refresh().catch(e=>error.value=e.message)},15000)})
onUnmounted(()=>{clearInterval(refreshTimer);delivery.value='';form.value={}})
watch(modal,value=>{if(!value){form.value={}}})
function openPlan(p?:any){form.value=p?{...p,applyExisting:false,traffic_gib:p.traffic_bytes/1073741824,rate_mbps:p.rate_bps*8/1000000}:{name:'',duration_days:30,duration_months:0,traffic_gib:500,traffic_period:'days',period_days:30,rate_mbps:0,max_concurrent:2};modal.value='plan'}
function openAccount(){form.value={route_id:'',plan_id:plans.value[0]?.id,username:'',password:'',start_mode:'immediate',expires_at:'',source_username:'',source_password:''};modal.value='account'}
async function savePlan(){await run(async()=>{const p={...form.value,traffic_bytes:Math.round(form.value.traffic_gib*1073741824),rate_bps:Math.round(form.value.rate_mbps*1000000/8)};delete p.traffic_gib;delete p.rate_mbps;const applyExisting=!!p.applyExisting;delete p.applyExisting;await api('access-plans'+(p.id?'/'+p.id:''),p.id?'PATCH':'POST',p);if(p.id&&applyExisting)await api('access-plans/'+p.id+'/apply','POST',{});modal.value='';await refresh();notice.value=applyExisting?'套餐已更新并应用到已有账号':'套餐已保存；已有订阅保持开通时的套餐值'})}
async function deletePlan(p:any){if(!confirm(`确认删除套餐「${p.name}」？已有账号使用的套餐不能删除。`))return;await run(async()=>{await api('access-plans/'+p.id,'DELETE');await refresh();notice.value='套餐已删除'})}
async function deleteAccount(row:any){if(!confirm(`确认删除账号「${row.account.username}」及其源站和登录记录？此操作无法恢复。`))return;await run(async()=>{await api('access-accounts/'+row.account.id,'DELETE');selected.value=null;await refresh();notice.value='账号已删除'})}
async function batchAccountAction(name:string,body:any,label:string){
 const ids=[...selectedAccountIds.value]
 if(!ids.length||!confirm(`确认对 ${ids.length} 个账号执行「${label}」？`))return
 await run(async()=>{for(const id of ids)await api('access-accounts/'+id+'/'+name,'POST',body);selectedAccountIds.value=[];await refresh();notice.value=`已对 ${ids.length} 个账号执行「${label}」`})
}
async function createAccount(){await run(async()=>{const f={...form.value,expires_at:form.value.expires_at?Math.floor(new Date(form.value.expires_at).getTime()/1000):0};const result=await api('access-accounts','POST',f);delivery.value=await importText(result.id,f.password,result.access_key);modal.value='';await refresh();notice.value='账号已开通。密码只展示本次，请保存导入信息'})}
async function importText(id:string,pass:string,key?:string){const all=await api('access-accounts');const c=all.find((v:any)=>v.account.id===id).account;const route=props.routes.find(r=>r.id===c.route_id);if(!c.route_id)return `用户中心：${location.origin}/?portal=1\n用户名：${c.username}\n密码：${pass||'使用开通时的密码，遗忘请联系管理员重置'}\n登录后自行添加 Emby，全部地址共享流量和有效期。`;if(!key){const keys=await api('routes/'+c.route_id+'/keys');key=keys.find((k:any)=>k.id===c.key_id)?.access_key}if(!route||!key)throw Error('路由或访问地址不可用');return `中转服务器地址：${location.origin}/r/${route.alias}/${key}/\n用户名：${c.username}\n密码：${pass||'（不保存明文，使用开通时的密码；遗忘请重置）'}\n到期时间：${c.started_at?date(c.expires_at):'首次登录后开始计时'}\n双向折算流量额度：${c.plan.traffic_bytes?bytes(c.plan.traffic_bytes):'不限'}\n提示：只使用以上中转信息，不需要真实 Emby 账号。`}
async function showImport(c:any){await run(async()=>{delivery.value=await importText(c.id,'')})}
async function showDetails(row:any){selected.value=row;await run(async()=>{sessions.value=await api('access-accounts/'+row.account.id+'/sessions')})}
function openAction(action:string){form.value={days:30,months:0,password:''};modal.value=action}
async function action(name:string,body:any){await api('access-accounts/'+selected.value.account.id+'/'+name,'POST',body);await refresh();sessions.value=await api('access-accounts/'+selected.value.account.id+'/sessions')}
async function saveAction(){await run(async()=>{const which=modal.value;const body=which==='renew'?{days:form.value.days,months:form.value.months}:{password:form.value.password};await action(which,body);if(which==='password')delivery.value=await importText(selected.value.account.id,body.password);modal.value='';notice.value='已更新'})}
const status=(c:any)=>!c.enabled?'已停用':c.expires_at&&c.expires_at<=Date.now()/1000?'已到期':!c.started_at?'待首次登录':'有效'
const sessionColumns=[{title:'设备 / 客户端',key:'device',ellipsis:{tooltip:true}},{title:'IP',key:'client_ip',ellipsis:{tooltip:true}},{title:'到期',key:'expires_at',render:(r:any)=>date(r.expires_at)}]
</script>
<template>
<div class="subscriptions">
<n-alert v-if="error" type="error" closable @close="error=''">{{error}}</n-alert><n-alert v-if="notice" type="success" closable @close="notice=''">{{notice}}</n-alert>
<section class="panel"><div class="panel-heading"><div><h3>访问账号与订阅</h3><span>独立登录 · 有效期 · 周期流量 · 手动续期</span></div><div class="actions"><n-button @click="run(refresh)">刷新</n-button><n-button type="primary" :disabled="!plans.length" @click="openAccount">开通账号</n-button></div></div>
<p class="subscription-note">先创建套餐，再开通用户账号。用户可在用户中心添加多个 Emby，所有地址共享账号额度与有效期。也可预先分配公共路由。流量按双向折算：下载 1 GiB，扣除 2 GiB。</p>
<div class="subscription-list-tools"><n-input v-model:value="accountSearch" clearable placeholder="搜索用户名" /><div v-if="selectedAccountIds.length" class="actions"><n-button size="small" @click="batchAccountAction('renew',{days:30,months:0},'续期 30 天')">续期 30 天</n-button><n-button size="small" @click="batchAccountAction('status',{enabled:false},'停用')">批量停用</n-button><n-button size="small" @click="batchAccountAction('revoke-sessions',{},'撤销登录')">撤销登录</n-button></div></div><div class="subscription-grid"><article v-for="row in visibleAccounts" :key="row.account.id" class="subscription-card"><div class="subscription-title"><label class="subscription-select"><input v-model="selectedAccountIds" type="checkbox" :value="row.account.id" :aria-label="'选择账号 '+row.account.username" /><h3>{{row.account.username}}</h3></label><n-tag size="small" :type="status(row.account)==='有效'?'success':'default'">{{status(row.account)}}</n-tag></div>
<dl><dt>路由 / 套餐</dt><dd>{{routes.find(r=>r.id===row.account.route_id)?.alias||(row.account.route_id?'路由已删除':'自助源站')}} · {{row.account.plan.name}}</dd><dt>剩余有效期</dt><dd>{{!row.account.started_at?'首次登录后生效':row.remaining_days<0?'不限':row.remaining_days+' 天'}}</dd><dt>本周期用量</dt><dd>{{bytes(row.used_bytes)}} / {{row.account.plan.traffic_bytes?bytes(row.account.plan.traffic_bytes):'不限'}}</dd><dt>下次重置</dt><dd>{{row.next_reset_at?date(row.next_reset_at):'不自动重置'}}</dd></dl>
<div class="actions"><n-button type="primary" secondary @click="showDetails(row)">查看详情</n-button><n-button @click="showImport(row.account)">导入信息</n-button><n-button type="error" quaternary @click="deleteAccount(row)">删除</n-button></div></article></div>
<n-pagination v-if="matchingAccounts.length>20" v-model:page="accountPage" :page-size="20" :item-count="matchingAccounts.length" class="subscription-pagination" /><p v-if="!accounts.length" class="subscription-note">暂无访问账号。套餐和订阅不涉及自动扣费。</p><p v-else-if="!matchingAccounts.length" class="subscription-note">没有匹配的账号。</p></section>
<section class="panel"><div class="panel-heading"><div><h3>套餐</h3><span>修改套餐仅影响之后开通的账号</span></div><n-button @click="openPlan()">添加套餐</n-button></div><div class="subscription-grid"><article v-for="p in plans" :key="p.id" class="subscription-card"><h3>{{p.name}}</h3><p>{{p.duration_months?p.duration_months+' 个月':p.duration_days?p.duration_days+' 天':'有效期不限'}} · {{p.traffic_bytes?bytes(p.traffic_bytes):'不限流量'}}</p><p>{{p.traffic_period==='total'?'累计额度':p.traffic_period==='month'?'UTC 自然月重置':'每 '+p.period_days+' 天重置'}} · {{p.max_concurrent}} 路播放</p><div class="actions"><n-button @click="openPlan(p)">编辑套餐</n-button><n-button type="error" quaternary @click="deletePlan(p)">删除</n-button></div></article></div></section>
<n-modal :show="!!selected" @update:show="v=>{if(!v)selected=null}" preset="card" title="订阅详情" :style="{width:'720px',maxWidth:'calc(100vw - 32px)'}"><template v-if="selected"><h3>{{selected.account.username}} · {{status(selected.account)}}</h3><dl class="subscription-fields"><dt>生效时间</dt><dd>{{selected.account.started_at?date(selected.account.started_at):'待首次登录'}}</dd><dt>到期时间</dt><dd>{{date(selected.account.expires_at)}}</dd><dt>已用 / 剩余流量</dt><dd>{{bytes(selected.used_bytes)}} / {{selected.account.plan.traffic_bytes?bytes(Math.max(0,selected.account.plan.traffic_bytes-selected.used_bytes)):'不限'}}</dd><dt>限速 / 并发</dt><dd>{{selected.account.plan.rate_bps?selected.account.plan.rate_bps*8/1000000+' Mbps':'不限速'}} / {{selected.account.plan.max_concurrent}} 路</dd></dl>
<div class="actions"><n-button type="primary" @click="openAction('renew')">续期</n-button><n-button @click="openAction('password')">重置登录密码</n-button><n-button @click="run(()=>action('status',{enabled:!selected.account.enabled}))">{{selected.account.enabled?'停用账号':'启用账号'}}</n-button><n-button @click="run(()=>action('revoke-sessions',{}))">撤销所有登录</n-button><n-button @click="run(()=>action('reset-usage',{}))">重置当前流量</n-button></div>
<UserSources :key="selected.account.id" :account-id="selected.account.id" compact />
<h3>登录会话</h3><n-data-table :columns="sessionColumns" :data="sessions" :table-layout="'fixed'" :pagination="{pageSize:5}" /><details v-for="s in sessions" :key="s.hash"><summary>{{s.client_ip}} · {{date(s.created_at)}}</summary><p style="overflow-wrap:anywhere">{{s.user_agent}}</p></details><n-alert v-if="error" type="error">{{error}}</n-alert></template></n-modal>
<n-modal :show="!!modal" @update:show="v=>{if(!v)modal=''}" preset="card" :title="modal==='plan'?'配置套餐':modal==='account'?'开通访问账号':modal==='renew'?'手动续期':'重置登录密码'" :style="{width:'560px',maxWidth:'calc(100vw - 32px)'}">
<n-form label-placement="top">
<template v-if="modal==='plan'"><n-form-item label="套餐名称"><n-input v-model:value="form.name" /></n-form-item><n-form-item label="有效天数（与有效月份二选一，均为 0 表示不限）"><n-input-number v-model:value="form.duration_days" :min="0" :max="36500" /></n-form-item><n-form-item label="有效月份（按开通日，月底自动对齐）"><n-input-number v-model:value="form.duration_months" :min="0" :max="1200" /></n-form-item><n-form-item label="双向折算额度（GiB，下载 1 GiB 扣 2 GiB；0 不限）"><n-input-number v-model:value="form.traffic_gib" :min="0" /></n-form-item><n-form-item label="流量周期"><n-select v-model:value="form.traffic_period" :options="[{label:'累计，不重置',value:'total'},{label:'每 N 天重置',value:'days'},{label:'UTC 自然月重置',value:'month'}]" /></n-form-item><n-form-item v-if="form.traffic_period==='days'" label="每多少天重置"><n-input-number v-model:value="form.period_days" :min="1" :max="36500" /></n-form-item><n-form-item label="账号共享限速（Mbps，0 不限）"><n-input-number v-model:value="form.rate_mbps" :min="0" /></n-form-item><n-form-item label="同时媒体请求上限（HLS 分片会分别占用）"><n-input-number v-model:value="form.max_concurrent" :min="1" :max="1000" /></n-form-item><n-form-item v-if="form.id" label="同时更新已有账号的套餐额度与规则"><n-switch v-model:value="form.applyExisting" /></n-form-item></template>
<template v-if="modal==='account'"><n-form-item label="中转路由"><n-select v-model:value="form.route_id" :options="routeOptions" /></n-form-item><n-form-item label="套餐"><n-select v-model:value="form.plan_id" :options="planOptions" /></n-form-item><n-form-item label="分配的用户名"><n-input v-model:value="form.username" autocomplete="off" /></n-form-item><n-form-item label="分配的密码（8–72 字节，仅本次可见）"><n-input v-model:value="form.password" type="password" show-password-on="click" autocomplete="new-password" /></n-form-item><n-form-item label="生效方式"><n-select v-model:value="form.start_mode" :options="[{label:'立即生效',value:'immediate'},{label:'首次成功登录生效',value:'first_login'}]" /></n-form-item><n-form-item label="固定到期时间（可选，覆盖套餐时长；按浏览器本地时区）"><input type="datetime-local" v-model="form.expires_at" /></n-form-item><n-form-item v-if="form.route_id" label="独立真实 Emby 用户名（可选，留空用源站账号）"><n-input v-model:value="form.source_username" /></n-form-item><n-form-item v-if="form.route_id" label="独立真实 Emby 密码（可选，加密存储）"><n-input v-model:value="form.source_password" type="password" autocomplete="new-password" /></n-form-item></template>
<template v-if="modal==='renew'"><p>未到期从原到期时间延长，已到期从现在开始。不会重置流量，也不会自动启用停用账号。</p><n-form-item label="增加天数（与月份二选一）"><n-input-number v-model:value="form.days" :min="0" :max="36500" /></n-form-item><n-form-item label="增加月份"><n-input-number v-model:value="form.months" :min="0" :max="1200" /></n-form-item></template>
<n-form-item v-if="modal==='password'" label="新登录密码（重置后旧 Token 立即失效）"><n-input v-model:value="form.password" type="password" autocomplete="new-password" /></n-form-item>
<n-alert v-if="error" type="error">{{error}}</n-alert><div class="modal-footer"><n-button @click="modal=''">取消</n-button><n-button type="primary" :loading="busy" @click="modal==='plan'?savePlan():modal==='account'?createAccount():saveAction()">保存</n-button></div></n-form></n-modal>
<n-modal :show="!!delivery" @update:show="v=>{if(!v)delivery=''}" preset="card" title="访问账号导入信息" :style="{width:'640px',maxWidth:'calc(100vw - 32px)'}"><ImportDetails :text="delivery" /><n-alert v-if="error" type="error">{{error}}</n-alert></n-modal>
</div>
</template>
<style scoped>
.subscription-list-tools{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:0 20px}.subscription-list-tools>.n-input{max-width:320px}.subscription-select{display:flex;align-items:center;gap:8px}.subscription-select h3{margin:0}.subscription-pagination{padding:0 20px 20px}.subscription-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:16px;padding:20px}.subscription-card{border:1px solid var(--line);border-radius:12px;padding:20px;min-width:0}.subscription-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.subscription-card h3{margin:0 0 12px}.subscription-card p,.subscription-note{color:var(--muted);font-size:13px;line-height:1.7}.subscription-note{padding:0 20px}.subscription-card dl,.subscription-fields{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;font-size:13px;line-height:1.6}.subscription-card dt,.subscription-fields dt{color:var(--muted)}.subscription-card dd,.subscription-fields dd{margin:0;overflow-wrap:anywhere}.actions{display:flex;gap:8px;flex-wrap:wrap}.subscription-card .actions{margin-top:20px}
</style>
